INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (4400991101010117, ARRAY['"A project topic is ''urban planning and forest management''. Which syllabus area best covers both?"'::jsonb, '"A local study compares a stepwell-like structure''s function with a modern rainwater harvesting system. Which syllabus connection is strongest?"'::jsonb, '"A course discussion separates a student''s learning stage from household responsibilities. Which sequence expresses the traditional transition?"'::jsonb, '"A class debates whether Karma and rebirth are the same word. Which statement best respects the syllabus framing?"'::jsonb, '"A report on ancient transport should distinguish movement of people/goods from the technology used to produce metal. Where do these topics appear?"'::jsonb, '"Which pairing best classifies a lesson on units of time, distance and weight?"'::jsonb, '"Which subject classification best fits an investigation of trade routes and historical transport methods?"'::jsonb, '"A project investigates the historical development of calendar calculation alongside astronomy. Which topic pair is most directly relevant?"'::jsonb, '"A student describes a Puranic work as an encyclopaedic source within the course''s classification. Which judgement best fits?"'::jsonb, '"A team has limited time for a BKS project and wants to connect ancient mathematics with modern relevance without overclaiming. Which scope fits the syllabus?"'::jsonb, '"A student wants to classify a study of how Sanskrit forms and analyses words. Which combination is the best match?"'::jsonb, '"An assignment studies iron production, textile dyeing and irrigation as evidence of technical knowledge. Which overall unit is appropriate?"'::jsonb, '"A student''s notes place Chandas under grammar and Vyakarana under metre. What correction is right?"'::jsonb, '"A researcher must select topics for a history of architecture. Which list is directly given in the syllabus?"'::jsonb, '"Which study plan best integrates astronomical timekeeping and agricultural knowledge?"'::jsonb, '"A student is preparing an evidence-based presentation on ancient technology and wants to avoid claiming that every practice was universal. Which approach is academically strongest?"'::jsonb, '"Which order places the four Ashramas in their conventional life-stage sequence?"'::jsonb, '"A student wants to study how metalworking and textile dyeing represent different technical practices. Which unit contains both?"'::jsonb, '"A student is explaining Purusharthas to a class. Which example best distinguishes Kama from Artha?"'::jsonb, '"A student has to map six Vedangas to their fields. Which mapping is wholly correct?"'::jsonb, '"An assignment considers both measurement units and the number system as related topics. Which unit is appropriate?"'::jsonb, '"A student mixes up Nirukta and Vyakarana. Which distinction corrects the notes?"'::jsonb, '"Which set contains only the four Vedas?"'::jsonb, '"A reading assignment asks students to distinguish Puranas from Itihasa as sources of knowledge. Which comparison best matches the syllabus?"'::jsonb, '"A lesson distinguishes town planning from temple architecture. Which broader tradition in the syllabus connects them?"'::jsonb, '"An assignment asks which goal of life concerns liberation rather than material prosperity. Which contrast is correct?"'::jsonb, '"A text analysis task examines Sanskrit grammar as potentially useful in natural language processing. What makes it relevant to the course?"'::jsonb, '"A student is asked to explain how a text handles ethical living, duty and liberation. Which framework is most relevant?"'::jsonb, '"A lesson compares how language sounds are articulated and how words are grammatically formed. Which pairing is accurate?"'::jsonb, '"A calendar project studies the astronomical basis of traditional timekeeping. Which topic should be consulted first?"'::jsonb]::jsonb[], ARRAY['"Sacred ecology and environment"'::jsonb, '"Word formatting"'::jsonb, '"Number system and units"'::jsonb, '"Language components"'::jsonb, '"Purusharthas and email writing"'::jsonb, '"Natural language processing"'::jsonb, '"Vedic metre and pronunciation"'::jsonb, '"Traditional water management and rainwater harvesting"'::jsonb, '"Sannyasa then Vanaprastha"'::jsonb, '"Grihastha then Brahmacharya"'::jsonb, '"Brahmacharya then Grihastha"'::jsonb, '"Moksha then Artha"'::jsonb, '"They are a pair of measurement units"'::jsonb, '"They are related philosophical concepts but named as separate topics"'::jsonb, '"They are identical Vedas"'::jsonb, '"They are HTML tags"'::jsonb, '"Both are Ashramas"'::jsonb, '"Both belong exclusively to grammar"'::jsonb, '"Neither appears in the provided syllabus"'::jsonb, '"Transport and metallurgy are separate subtopics within the technology unit"'::jsonb, '"Number system and units of measurement"'::jsonb, '"CSS positioning systems"'::jsonb, '"Vedic schools of philosophy only"'::jsonb, '"Textile dyeing"'::jsonb, '"Transportation and development of trading techniques"'::jsonb, '"CSS text effects"'::jsonb, '"Purusharthas only"'::jsonb, '"Vedic phonetics"'::jsonb, '"Vedanga Jyotish and measuring time/calendar"'::jsonb, '"Vastu and email systems"'::jsonb, '"Purusharthas and printer technology"'::jsonb, '"Nirukta and textile dyeing"'::jsonb, '"It contradicts the provided unit title"'::jsonb, '"It fits the syllabus description of Puranas"'::jsonb, '"It treats a Vedanga as a storage device"'::jsonb, '"It confuses Puranas with CSS sheets"'::jsonb, '"Claim every modern formula was invented in one period"'::jsonb, '"Replace mathematical explanation with temple descriptions"'::jsonb, '"Compare a specific arithmetic, geometry, trigonometry or algebra concept with a clearly stated modern use"'::jsonb, '"Skip the source and present a list of names only"'::jsonb, '"Textile dyeing and trading techniques"'::jsonb, '"Language components, Sanskrit and language-science concepts"'::jsonb, '"Ashramas and Moksha only"'::jsonb, '"Water management, irrigation and architecture"'::jsonb, '"Concepts of Life only"'::jsonb, '"Engineering, Technology and Architecture in Ancient Bharat"'::jsonb, '"Reading Skills"'::jsonb, '"Science and Mathematics only"'::jsonb, '"Chandas is metre; Vyakarana is grammar"'::jsonb, '"Chandas is etymology; Vyakarana is language pronunciation"'::jsonb, '"Chandas is astronomy; Vyakarana is architecture"'::jsonb, '"Both are ritual procedures"'::jsonb, '"CPU buses, BIOS and RAM"'::jsonb, '"Email attachments, CC and BCC"'::jsonb, '"Town planning, civil architecture and temple architecture"'::jsonb, '"CSS gradients, tooltips and web fonts"'::jsonb, '"Study only HTML input elements"'::jsonb, '"Study only the Ashrama sequence"'::jsonb, '"Study printer mechanisms and ports"'::jsonb, '"Study Vedanga Jyotish/calendar concepts alongside Nakshatrara Gyaan and agriculture"'::jsonb, '"Exclude dates and conditions to sound more certain"'::jsonb, '"Replace historical evidence with a modern slogan"'::jsonb, '"Describe the specific example and available evidence, separating documented detail from generalization"'::jsonb, '"Assume one example proves all regions used the same method"'::jsonb, '"Grihastha, Sannyasa, Brahmacharya, Vanaprastha"'::jsonb, '"Brahmacharya, Grihastha, Vanaprastha, Sannyasa"'::jsonb, '"Vanaprastha, Brahmacharya, Moksha, Artha"'::jsonb, '"Dharma, Artha, Kama, Moksha"'::jsonb, '"Concepts of Life"'::jsonb, '"Engineering, Technology and Architecture in Ancient Bharat"'::jsonb, '"Introduction to BKS only"'::jsonb, '"Reading Skills"'::jsonb, '"Kama concerns desire/enjoyment; Artha concerns material means/prosperity"'::jsonb, '"Both are names of Vedas"'::jsonb, '"Kama means liberation; Artha means rebirth"'::jsonb, '"Kama concerns grammar; Artha concerns metre"'::jsonb, '"Nirukta—water management; Chandas—grammar; Jyotisha—textiles"'::jsonb, '"Jyotisha—grammar; Chandas—ritual procedures; Shiksha—architecture"'::jsonb, '"Shiksha—metre; Kalpa—astronomy; Vyakarana—dyeing"'::jsonb, '"Shiksha—phonetics; Kalpa—ritual procedures; Vyakarana—grammar"'::jsonb, '"Science and Mathematics in Ancient Bharat"'::jsonb, '"Concepts of Life"'::jsonb, '"CSS3"'::jsonb, '"Communication Skills"'::jsonb, '"Nirukta focuses on word etymology/explanation; Vyakarana focuses on grammar"'::jsonb, '"Nirukta is a Veda; Vyakarana is a Purana"'::jsonb, '"Nirukta concerns calendars; Vyakarana concerns water storage"'::jsonb, '"Both refer only to poetic metre"'::jsonb, '"Atharvaveda, Chandas, Vastu, Rigveda"'::jsonb, '"Rigveda, Samaveda, Yajurveda, Atharvaveda"'::jsonb, '"Samaveda, Nyaya, Mimamsa, Yajurveda"'::jsonb, '"Rigveda, Purana, Kalpa, Atharvaveda"'::jsonb, '"Puranas refer only to measurements and Itihasa only to grammar"'::jsonb, '"Both are Vedangas for metre"'::jsonb, '"Both are modern scientific journals"'::jsonb, '"Puranas are described as encyclopaedic works; Itihasa is framed as a source of wisdom"'::jsonb, '"Vedanga grammar"'::jsonb, '"Chandas"'::jsonb, '"Vastu Shastra / science of architecture"'::jsonb, '"Mail merge"'::jsonb, '"Artha rather than Moksha"'::jsonb, '"Dharma rather than Jyotisha"'::jsonb, '"Kama rather than Chandas"'::jsonb, '"Moksha rather than Artha"'::jsonb, '"It concerns only the measurement of weight"'::jsonb, '"The syllabus treats Sanskrit only as a metalworking method"'::jsonb, '"NLP is listed under temple floor plans"'::jsonb, '"The syllabus explicitly links Sanskrit''s role with natural language processing"'::jsonb, '"Serial and parallel ports"'::jsonb, '"Measurement of weight only"'::jsonb, '"Purusharthas and Moksha"'::jsonb, '"CSS box model"'::jsonb, '"Chandas—articulation; Kalpa—grammar"'::jsonb, '"Vastu—articulation; Artha—grammar"'::jsonb, '"Shiksha—articulation; Vyakarana—grammar"'::jsonb, '"Jyotisha—articulation; Nirukta—grammar"'::jsonb, '"Purusharthas"'::jsonb, '"Vedanga Jyotish"'::jsonb, '"Textile dyeing"'::jsonb, '"Temple plans"'::jsonb]::jsonb[], ARRAY['0'::jsonb, '3'::jsonb, '2'::jsonb, '1'::jsonb, '3'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '1'::jsonb, '2'