VALUES (4400913121010117, ARRAY['"For P(x)=2x²−3x+1, find P(−2)."'::jsonb, '"A sphere has radius 3 cm. Volume?"'::jsonb, '"Rhombus diagonals 10 cm and 24 cm. Area?"'::jsonb, '"A right triangle has opposite and adjacent legs 5 and 12. Find sec θ."'::jsonb, '"Alarms sound every 18, 24 and 30 minutes. When next together?"'::jsonb, '"Simplify (x+3)²−(x−3)²."'::jsonb, '"Simplify (2x²y)(−3xy³)."'::jsonb, '"Express 0.375 as a fraction in lowest terms."'::jsonb, '"If sin θ=3/5 and cos θ=4/5, find sin 2θ."'::jsonb, '"Simplify (x+2)²−(x−2)²."'::jsonb, '"If cos θ=4/5 for acute θ, find tan θ."'::jsonb, '"Factor x²−7x+12."'::jsonb, '"Using the standard fraction rule, find HCF of 3/4 and 9/10."'::jsonb, '"Simplify (a³b²)²÷(a⁴b), for non-zero a,b."'::jsonb, '"For acute θ, tan θ=1/√3. Find θ."'::jsonb, '"Simplify (2³×2⁻¹)÷2²."'::jsonb, '"Trapezium parallel sides 8 cm,14 cm; height 5 cm. Area?"'::jsonb, '"Cylinder radius 3 cm, height 7 cm. Volume?"'::jsonb, '"At 150° on the unit circle, find (cos θ,sin θ)."'::jsonb, '"If sin θ=5/13 for acute θ, find tan θ."'::jsonb, '"Evaluate 2 sin 30° cos 30°."'::jsonb, '"Bells ring every 12, 15 and 20 minutes. When next together?"'::jsonb, '"Cylinder radius 2 cm, height 10 cm. Volume?"'::jsonb, '"A 4.8 m×3.6 m floor uses largest square tiles without cutting. Tile side?"'::jsonb, '"If x+y=9 and xy=14, find x²+y²."'::jsonb, '"Simplify (5⁴÷5²)×5⁻¹."'::jsonb, '"Cuboid 10 cm×8 cm×6 cm. Total surface area?"'::jsonb, '"Expand (3x−2)(x+4)."'::jsonb, '"If cos θ=1/2 for acute θ, find sin 2θ."'::jsonb, '"Find HCF of 0.24 and 0.36."'::jsonb]::jsonb[], ARRAY['"3"'::jsonb, '"15"'::jsonb, '"7"'::jsonb, '"11"'::jsonb, '"36π cm³"'::jsonb, '"18π cm³"'::jsonb, '"27π cm³"'::jsonb, '"9π cm³"'::jsonb, '"240 cm²"'::jsonb, '"120 cm²"'::jsonb, '"60 cm²"'::jsonb, '"34 cm²"'::jsonb, '"5/13"'::jsonb, '"12/13"'::jsonb, '"13/5"'::jsonb, '"13/12"'::jsonb, '"120 min"'::jsonb, '"360 min"'::jsonb, '"240 min"'::jsonb, '"180 min"'::jsonb, '"12x"'::jsonb, '"2x²+18"'::jsonb, '"18"'::